alter table public.player_action_sets drop constraint if exists player_action_sets_slots_check;
alter table public.player_action_sets add constraint player_action_sets_slots_check
  check (jsonb_typeof(slots) = 'array' and jsonb_array_length(slots) <= 20);
-- The timeline's event types are EVENT_COPY's keys.
alter table public.hunt_session_events drop constraint if exists hunt_session_events_type_check;
alter table public.hunt_session_events add constraint hunt_session_events_type_check
  check (type in ('entered', 'level_up', 'rare_drop', 'death', 'slot_dry', 'stamina_low', 'cover', 'ended'));
-- THE LAST NON-HUNT ACTIVITY an automatic hunt end resumes (Tyler 2026-10-14).
alter table public.player_state add column if not exists last_activity_kind text;
alter table public.player_state add column if not exists last_activity_id text;
alter table public.player_state alter column last_activity_kind drop default;
alter table public.player_state alter column last_activity_id drop default;
alter table public.player_state drop constraint if exists player_state_last_activity_ck;
alter table public.player_state add constraint player_state_last_activity_ck
  check ((last_activity_kind is null) = (last_activity_id is null)
         and (last_activity_kind is null or last_activity_kind in ('gather', 'artisan', 'training'))
         and (last_activity_id is null or last_activity_id ~ '^[a-z0-9_]{1,64}$'));
delete from public.hr_hunt_vendor_value;

-- ── SELF-CHECK (CLAUDE.md §4): the rows the generator wrote, and nothing more ──
do $$
declare v_role text; v_t text;
begin
  if (select count(*) from public.hr_hunt_supplies) <> 82
     or (select count(*) from public.hr_hunt_travel) <> 128
     or (select count(*) from public.hr_hunt_limits) <> 48
     or (select count(*) from public.hr_hunt_end_reasons) <> 13
     or (select count(*) from public.hr_hunt_vendor_value) <> 547
     or (select count(*) from public.hr_hunt_basic_supplies) <> 26
     or (select count(*) from public.hr_hunt_cover_items) <> 0
     or exists (select 1 from public.hr_hunt_basic_supplies where cardinality(coalesce(tiers, '{}'::int[])) > 0)
     or exists (select 1 from public.hr_hunt_travel where tier is not null)
     or (select count(*) from public.hr_hunt_target_modes) <> 5
     or (select count(*) from public.hr_hunt_resumable_kinds) <> 3
     or (select count(*) from public.hr_hunt_lanes) <> 4
     or (select count(*) from public.hr_hunt_set_options) <> 10
     or (select count(*) from public.hr_hunt_kill_bounds) <> 140
     or (select count(*) from public.hr_hunt_abilities) <> 16
     or (select count(*) from public.hr_hunt_grounds) <> 6
     or (select count(*) from public.hr_hunt_grounds where density_max is null) <> 0
     or (select count(*) from public.hr_hunt_ground_spawns) <> 30
     or (select count(*) from public.hr_hunt_roster) <> 30
     or (select count(*) from public.hr_hunt_world_shape) <> 1
     or (select count(*) from public.hr_premium_login_reward) <> 1
     or (select count(*) from public.hr_hunt_weapons) <> 66
     or (select count(*) from public.hr_hunt_weapon_roles) <> 12
     or (select count(*) from public.hr_hunt_roles) <> 0
     or (select count(*) from public.hr_hunt_shields) <> 6
     or exists (select 1 from public.hr_hunt_weapon_roles where discipline is null)
     or exists (select 1 from public.hr_hunt_weapon_roles w where w.with_shield is not null
                 and not exists (select 1 from public.hr_hunt_weapon_roles k where k.weapon_type = w.with_shield))
     or (select count(*) from public.hr_hunt_end_reasons where resumes) <> 11 then
    raise exception 'hunt-session catalogue row counts moved from the generator''s'; end if;
  -- Every ground's respawn is the data's (the settle's kill bound reads it: 2027-02-09, the Cellar at 32 s).
  if exists (select 1 from public.hr_hunt_grounds g where (g.ground_id, g.respawn_ms) not in
               (('coppercap_warrens', 90000), ('meadowbrook_thicket', 60000), ('mill_cellar', 32000), ('millrace_sewer', 90000), ('mosslight_glade', 60000), ('wickstead', 60000))) then
    raise exception 'a hunt ground''s respawn_ms is not hunt-grounds.js respawnMs'; end if;
  -- The world fields the party section reads by name are all there, at the generator's positions.
  if (select fields from public.hr_hunt_world_shape) is distinct from '{"unit":{"id":0,"side":1,"kind":2,"pocket":3,"alive":4,"hp":5,"maxHp":6,"target":7,"home":8,"x":9,"y":10,"fx":11,"fy":12,"prog":13,"speed":14,"dir":15,"goal":16,"path":17,"waitMs":18,"repathMs":19,"spot":20,"holdMs":21,"role":22,"dist":23,"chase":24,"tmode":25,"queued":26,"aiMs":27,"deadMs":28,"hpMilli":29,"yieldPm":30,"stance":31,"acc":32,"maxHit":33,"def":34,"element":35,"swingLeftMs":36,"mana":37,"maxMana":38,"manaMilli":39,"regenPm":40,"lanes":41,"cds":42,"shield":43,"markPm":44,"markUntil":45,"statuses":46,"laneAt":47,"otHp":48,"otMana":49,"ruleHold":50,"ruleWait":51},"world":{"ground":0,"swing":1,"leader":2,"trail":3,"leaderLast":4,"hold":5,"holdNext":6,"phase":7,"routeIdx":8,"phaseMs":9,"regroupNext":10,"runs":11,"nextId":12,"density":13,"fightAt":14,"xpGroup":15,"rareWon":16}}'::jsonb
     or exists (select 1 from unnest(array['id', 'side', 'kind', 'alive', 'x', 'y', 'hp', 'maxHp', 'target', 'mana', 'maxMana', 'shield', 'otHp', 'otMana', 'role', 'dist', 'chase', 'tmode', 'stance']) n
                 where not ((select fields->'unit' from public.hr_hunt_world_shape) ? n)) then
    raise exception 'hr_hunt_world_shape.fields is not world-state.js FIELDS'; end if;
  -- ONE consumable lane, at the data file's ms (the food-lane ruling, spec §3.4 #3).
  if (select ms from public.hr_hunt_lanes where lane = 'consumable') is distinct from 2000 then
    raise exception 'the consumable lane is not consumables.js laneMs'; end if;
  -- Premium may never rest less than free; the core model's curves are live (a Level and a skill both start at 0 XP:
  -- the Level curve's own rows, hr_level_curve, and the skill curve's base).
  if public.hr_hunt_limit('stamina_premium_min') < public.hr_hunt_limit('stamina_free_min')
     or public.hr_hunt_limit('level_cubic') is not null
     or coalesce(public.hr_char_xp_for_level(2), 0) <= 0 or coalesce(public.hr_hunt_limit('skill_base'), 0) <= 0
     or coalesce(public.hr_hunt_limit('armour_slots'), 0) <= 0 then
    raise exception 'the stamina caps or the core model rows are malformed'; end if;
  -- Every supply, vendor value, ability rune and login reward is a catalogued item;
  -- every named hunt and ground hunt is in hr_hunts; every training id is a
  -- non-boss combat target; every ground spawn has a kill bound.
  if exists (select 1 from public.hr_hunt_supplies s where not exists (select 1 from public.hr_items i where i.item_id = s.item_id))
     or exists (select 1 from public.hr_hunt_vendor_value v where not exists (select 1 from public.hr_items i where i.item_id = v.item_id))
     or exists (select 1 from public.hr_hunt_abilities a where a.active and a.rune is not null
                  and not exists (select 1 from public.hr_items i where i.item_id = a.rune))
     or exists (select 1 from public.hr_premium_login_reward l where l.item_id is not null
                  and not exists (select 1 from public.hr_items i where i.item_id = l.item_id)) then
    raise exception 'a supply, vendor-value, ability-rune or login-reward row names an item hr_items does not have'; end if;
  if exists (select 1 from public.hr_hunt_travel t where not t.training
               and not exists (select 1 from public.hr_hunts h where h.hunt_id = t.hunt_id))
     or exists (select 1 from public.hr_hunt_grounds g where not exists (select 1 from public.hr_hunts h where h.hunt_id = g.hunt_id)) then
    raise exception 'a named hunt or a ground hunt is not in hr_hunts'; end if;
  if exists (select 1 from public.hr_hunt_travel t where t.training
               and not exists (select 1 from public.hr_activities a
                                where a.kind = 'combat' and a.activity_id = t.hunt_id and not a.is_boss)) then
    raise exception 'a training id in hr_hunt_travel is not a non-boss combat target'; end if;
  if exists (select 1 from public.hr_hunt_ground_spawns s
               where not exists (select 1 from public.hr_hunt_kill_bounds b where b.monster_id = s.monster_id)) then
    raise exception 'a ground spawns a monster with no kill bound'; end if;
  -- THE DROP BOUNDS (2027-02-10, the Brook Bear): every item a monster of a ground can drop (src/data/monsters.js
  -- over each pocket's whole pack) has, on that ground, the settle's OWN item bound (hr_hunt_apply_instance (4c):
  -- the most rows naming it over the kill bounds of the ground's spawn rows) at least the rows one kill names it.
  -- A 0 here is a hunt the settle refuses value_over on the first such drop.
  select d.hunt_id || ' ' || d.item_id into v_t from (values
    ('coppercap_warrens', 'big_bones', 1),
